// App wiring: input detection, decode pipeline, events.
(function () {
  'use strict';
  const $ = (id) => document.getElementById(id);
  // Demo data is synthetic (generated by test/gen_example.py from the public BIP39 test mnemonic).
  const EXAMPLE_PSBT = '';
  const EXAMPLE_TX = '';

  let current = null; // {model, analysis}

  // Embed mode: ?embed=1 shows only verdict + stats + money flow (see css)
  // and reports the document height to the embedding page so an iframe can
  // size itself. Only a number is posted; the parent is not otherwise touched.
  const params = new URLSearchParams(location.search);
  const embed = params.has('embed');
  if (embed) document.body.classList.add('embed');
  function postHeight() {
    if (!embed || window.parent === window) return;
    parent.postMessage({ type: 'psbt-decoder:height', height: document.documentElement.scrollHeight }, '*');
  }
  if (embed && 'ResizeObserver' in window) new ResizeObserver(postHeight).observe(document.body);

  function toBytes(text) {
    const s = text.replace(/\s+/g, '');
    if (!s) throw new Error('Paste a PSBT (base64/hex) or a raw transaction (hex).');
    if (Bytes.isHex(s)) return Bytes.hexToBytes(s);
    if (Bytes.isBase64(s)) { try { return Bytes.base64ToBytes(s); } catch (e) { throw new Error('Input looks like base64 but could not be decoded.'); } }
    throw new Error('Input is neither valid hex nor base64.');
  }

  function decodeBytes(bytes, network) {
    let model;
    if (Psbt.isPsbt(bytes)) {
      const parsed = Psbt.parsePsbt(bytes);
      model = Psbt.buildModel(parsed, 'psbt', network);
    } else {
      const segments = [];
      let tx;
      try { tx = Tx.parseTx(bytes, { segments }); }
      catch (e) { throw new Error(`Not a PSBT (no "psbt\\xff" magic) and not a valid raw transaction: ${e.message}`); }
      tx.segments = segments; tx.warnings = [];
      model = Psbt.buildModel(tx, 'rawtx', network);
      model.segments = segments; model.bytes = bytes;
    }
    return model;
  }

  function render(model) {
    const a = Analysis.analyze(model);
    current = { model, analysis: a };
    UI.renderVerdict($('verdict'), model, a);
    UI.renderStats($('stats'), model, a);
    UI.renderFlow($('flow'), model, a);
    UI.renderMoneyBar($('moneybar'), model, a);
    UI.renderChecks($('checks'), a);
    UI.renderInputs($('inputs'), model);
    UI.renderOutputs($('outputs'), model);
    UI.renderScripts($('scripts'), model);
    UI.renderHex($('hexlegend'), $('hexinfo'), $('hexview'), model);
    UI.renderPsbtFields($('psbtfields'), model);
    $('json').textContent = UI.toJSON(model, a);
    $('n-in').textContent = model.inputs.length;
    $('n-out').textContent = model.outputs.length;
    $('copyfinal').style.display = model.finalTx ? '' : 'none';
    $('results').style.display = '';
    // auto-open small lists
    if (model.inputs.length <= 3) $('inputs').querySelectorAll('.card').forEach(c => c.classList.add('open'));
    if (model.outputs.length <= 3) $('outputs').querySelectorAll('.card').forEach(c => c.classList.add('open'));
    postHeight();
  }

  function showError(msg) { const e = $('error'); e.textContent = msg; e.style.display = 'block'; $('results').style.display = 'none'; current = null; postHeight(); }
  function clearError() { $('error').style.display = 'none'; }

  let lastBytes = null;
  function decode(scroll = true) {
    clearError();
    try {
      lastBytes = toBytes($('input').value);
      render(decodeBytes(lastBytes, $('network').value));
      if (scroll) $('results').scrollIntoView({ behavior: 'smooth', block: 'start' });
    } catch (e) { console.error(e); showError('Decode failed: ' + e.message); }
  }

  $('decode').onclick = () => decode(true);
  $('input').addEventListener('keydown', (e) => { if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') decode(); });
  $('network').onchange = () => { if (lastBytes) { try { render(decodeBytes(lastBytes, $('network').value)); } catch (e) { showError(e.message); } } };
  $('clear').onclick = () => { $('input').value = ''; clearError(); $('results').style.display = 'none'; lastBytes = null; };
  $('example').onclick = () => { $('input').value = EXAMPLE_PSBT; decode(); };
  $('exampletx').onclick = () => { $('input').value = EXAMPLE_TX; decode(); };
  $('paste').onclick = async () => { try { $('input').value = await navigator.clipboard.readText(); decode(); } catch (e) { showError('Clipboard access denied — paste manually (Ctrl/Cmd+V).'); } };
  $('fileBtn').onclick = () => $('file').click();
  $('file').onchange = (e) => { if (e.target.files[0]) loadFile(e.target.files[0]); e.target.value = ''; };

  function loadFile(file) {
    const fr = new FileReader();
    fr.onload = () => {
      const bytes = new Uint8Array(fr.result);
      if (Psbt.isPsbt(bytes)) { $('input').value = Bytes.bytesToBase64(bytes); decode(); return; }
      // maybe text
      const text = new TextDecoder().decode(bytes).trim();
      if (/^[0-9a-fA-F\s]+$/.test(text) || /^[A-Za-z0-9+/=\s_-]+$/.test(text)) { $('input').value = text; decode(); }
      else { $('input').value = Bytes.bytesToHex(bytes); decode(); }
    };
    fr.readAsArrayBuffer(file);
  }
  const panel = $('input-panel');
  ['dragenter', 'dragover'].forEach(ev => panel.addEventListener(ev, (e) => { e.preventDefault(); panel.classList.add('drop-active'); }));
  ['dragleave', 'drop'].forEach(ev => panel.addEventListener(ev, (e) => { e.preventDefault(); panel.classList.remove('drop-active'); }));
  panel.addEventListener('drop', (e) => { const f = e.dataTransfer.files[0]; if (f) loadFile(f); });

  // Tabs
  $('tabs').addEventListener('click', (e) => {
    const b = e.target.closest('button'); if (!b) return;
    $('tabs').querySelectorAll('button').forEach(x => x.classList.toggle('active', x === b));
    document.querySelectorAll('.tabpane').forEach(p => p.classList.toggle('active', p.id === 'tab-' + b.dataset.tab));
  });
  // Card toggle, hex toggle, copy
  document.addEventListener('click', (e) => {
    const copy = e.target.closest('.copy');
    if (copy) { navigator.clipboard.writeText(copy.dataset.copy).then(() => { copy.textContent = 'copied'; setTimeout(() => copy.textContent = 'copy', 1200); }); e.stopPropagation(); return; }
    const th = e.target.closest('.togglehex');
    if (th) { th.closest('.scriptblock').classList.toggle('showhex'); return; }
    const head = e.target.closest('.card .head');
    if (head && !e.target.closest('a')) head.parentElement.classList.toggle('open');
  });
  $('copyjson').onclick = () => navigator.clipboard.writeText($('json').textContent);
  $('copyfinal').onclick = () => { if (current && current.model.finalTx) navigator.clipboard.writeText(current.model.finalTx.hex); };

  // Support ?psbt=... / #... in URL for convenience. ?network=<mainnet|testnet|signet|regtest>
  // selects the address encoding. Prefer the #fragment for data: it is never sent to a server.
  const netParam = params.get('network');
  if (netParam && $('network').querySelector(`option[value="${netParam}"]`)) $('network').value = netParam;
  const fromUrl = params.get('psbt') || params.get('tx') || (location.hash.length > 1 ? decodeURIComponent(location.hash.slice(1)) : '');
  if (fromUrl) {
    $('input').value = fromUrl; decode(false);
    const tab = params.get('tab');
    if (tab) { const b = $('tabs').querySelector(`button[data-tab="${tab}"]`); if (b) b.click(); }
  }
})();
